define(["jquery"],function($){"use strict";function init(config){if(!config||!config.url){return}let $container=$('[data-region="password-admin-content"]');let $meta=$('[data-region="password-admin-meta"]');if($container.length===0){return}let loading=false;let refresh=function(){if(loading){return}loading=true;$.ajax({url:config.url,method:"GET",dataType:"json"}).done(function(response){if(!response){return}if(typeof response.html==="string"){$container.html(response.html)}if($meta.length&&response.lastupdated){$meta.text(M.util.get_string("admin_refreshing","proctoringpolicy_password")+" "+response.lastupdated)}}).always(function(){loading=false})};window.setInterval(refresh,Number(config.interval||1e4))}return{init:init}});